mapper.select:
select t.task_id, t.proj_id, p.proj_no, p.proj_nm, t.task_nm, t.owner_user_id, t.plan_start, t.plan_end, t.plan_hours, t.status
  from pms_task t join pms_project p on p.proj_id = t.proj_id
 where t.is_summary = 'N' and t.task_type = 'TASK' and t.status <> 'CANCELLED' and p.status <> 'CANCELLED'
   and t.plan_hours > 0 and t.plan_start <= #{to} and t.plan_end >= #{from}
and t.proj_id = #{projId}
and t.owner_user_id = #{ownerId}
and t.owner_user_id is null
 order by t.plan_start, t.task_id
 limit #{limit}

select w.user_id, date_trunc('week', w.work_day::timestamp)::date as week_start, sum(w.hours) as hours
  from pms_work_log w
 where w.status = 'CONFIRMED' and w.work_day between #{from} and #{to}
and w.proj_id = #{projId}
 group by w.user_id, date_trunc('week', w.work_day::timestamp)::date


select u.user_id, u.login_id, u.user_nm, u.use_yn
  from unnest(array[#{i}]::bigint[]) as x(id)
  join sys_user u on u.user_id = x.id
